-- S7: 14 juicios, AUTO exclusivamente, configuraciones aprobadas y puente trazable.
BEGIN;
DO $j$
DECLARE p jsonb; e record; h text; val jsonb; ans jsonb; cd text; n int:=0; pub int:=0; ret int:=0; b_leg jsonb; b_dep jsonb; diff text; residual text; status text; lid int; old_desc text; new_desc text; diffs jsonb:=$diff${"S7-C06":"Conserva código, expiración e intentos en reenvío de OTP vigente; renovación solo tras vencimiento o agotamiento y controles aplicables.","S7-C07":"Conserva autenticación primaria, token opaco, hash persistido, expiración, revocación y atributos de cookie; no otorga sesión por token solo.","S7-C08":"Conserva exclusión del enrolamiento TOTP histórico y necesidad de nueva decisión para reintroducirlo.","S7-C09":"Conserva invalidación del contexto de recuperación y nuevo login completo; no convierte recuperación en sesión operativa.","S7-C10":"Conserva anti-enumeración específica de recuperación incluso ante fallos del proveedor y contador independiente de existencia de cuenta.","S7-C11":"Conserva mensaje operativo seguro con acción y referencia; binding CTA pendiente, no demuestra renderizado.","S5-C12":"Complementa M4-B01 mediante control de expires_at desde created_at y otp_verified_at nulo; persiste residual de abandono sin columna de estado.","S6-C03":"Complementa S5-C13 y S2-C02 con persistencia de blocked_at al agotar último reenvío y nuevo onboarding."}$diff$::jsonb;
BEGIN
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO b_leg FROM lf_ops.reglas t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones t;
 FOR p IN SELECT value FROM jsonb_array_elements($pack$[{"codigo":"S7-C01","version":1,"eval_id":632,"hash_paquete_atestado":"70f6b3b4d70305341f29dbe7db5307619dedd544c95657bef278c7d3602eddc8","veredicto":"DEVOLVER","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"Decisión pendiente: fuente y versión inmutable del snapshot contractual de cuotas."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":528,"familia":"FINANCIAL_INTEGRITY_RECONCILIATION"},{"codigo":"S7-C02","version":1,"eval_id":633,"hash_paquete_atestado":"17b11c965953f0cc32fa8e6a5b6b9971eac41a2d3d3ef2bdb63edee6de5afc8b","veredicto":"DEVOLVER","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"Decisión pendiente: fuente canónica de liquidaciones, pagos y ajustes autorizados."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":606,"familia":"FINANCIAL_INTEGRITY_RECONCILIATION"},{"codigo":"S7-C03","version":1,"eval_id":634,"hash_paquete_atestado":"777182c5b8193f803f4b93d214a8f50090be1cf5330b93536c4f35d2a4d0548a","veredicto":"DEVOLVER","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"Decisión pendiente: ruta de devolución y separación de beneficio comercial."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":625,"familia":"FINANCIAL_INTEGRITY_RECONCILIATION"},{"codigo":"S7-C04","version":1,"eval_id":635,"hash_paquete_atestado":"b365f377d95334a6ef091ea88d920839e8e970d480aa7a7b1c22a81356d657d5","veredicto":"DEVOLVER","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"Decisión pendiente: modalidad contractual y control de exclusión de cobros paralelos."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":530,"familia":"FINANCIAL_INTEGRITY_RECONCILIATION"},{"codigo":"S7-C05","version":1,"eval_id":636,"hash_paquete_atestado":"22ab1b6f0df1cc31b122f1dda1d8e79f870f2f235c492bca8ac6fe416dd113c7","veredicto":"DEVOLVER","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"Identidad del contador de recuperación y referencia de secreto HMAC runtime no verificadas."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":501,"familia":"RATE_LIMIT"},{"codigo":"S7-C06","version":1,"eval_id":637,"hash_paquete_atestado":"b87097c1f296bc043cb562c6ca99e5d7485389ca91878360f0ad38f10e140f26","veredicto":"PASS","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":498,"familia":"MFA_OTP_SSO"},{"codigo":"S7-C07","version":1,"eval_id":638,"hash_paquete_atestado":"3d565e327fc3b0da57a29083352a311a80c8254f67cee48e900b09ccbf4004cb","veredicto":"PASS","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":0.9,"observacion":"Especificación de cookie larga."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":497,"familia":"MFA_OTP_SSO"},{"codigo":"S7-C08","version":1,"eval_id":639,"hash_paquete_atestado":"d6b753429b76602cd1a0703d0fc1b4954f5a23bacba63e5ff37def8f0342a63e","veredicto":"PASS","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":454,"familia":"MFA_OTP_SSO"},{"codigo":"S7-C09","version":1,"eval_id":640,"hash_paquete_atestado":"ba99d8049f9baaaa0136e31266a10861596cc991a415ece9afbffe2aad61d894","veredicto":"PASS","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":450,"familia":"SESSION"},{"codigo":"S7-C10","version":1,"eval_id":641,"hash_paquete_atestado":"678a32fc1d44f9c3016d17afb38ce96c07519e63b5f590565f6957e3ec5f8df8","veredicto":"PASS","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.8,"observacion":"Cerca de S5-C23 y S7-C05."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":446,"familia":"MFA_OTP_SSO"},{"codigo":"S7-C11","version":1,"eval_id":642,"hash_paquete_atestado":"f0d784961d13fbb57e9b74d0675c5fb83c28a54c77608099c26fd6837970867a","veredicto":"PASS","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":0.9,"observacion":"Referencia y acción requieren binding operativo."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":410,"familia":"SECURITY"},{"codigo":"S7-C12","version":1,"eval_id":643,"hash_paquete_atestado":"d305fa4a089f21a0839cd41fd77db08eeb0c9e3f8b945da15825e63470e030b6","veredicto":"DEVOLVER","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":0.5,"observacion":"Decisión pendiente: evidencia autoritativa de envío y contrato de handoff."},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":540,"familia":"PAYMENTS_CHECKOUT"},{"codigo":"S5-C12","version":2,"eval_id":644,"hash_paquete_atestado":"c228404ce00eeef5935be6154b2d6f4f7615ec274742e3021298b4433e142383","veredicto":"PASS","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"Complementa M4-B01 sobre expiración."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":14,"familia":"SESSION"},{"codigo":"S6-C03","version":2,"eval_id":645,"hash_paquete_atestado":"645d3339f40681b6e73919269ec80c4ba06b23c2583776220b4ab21d80ba031a","veredicto":"PASS","juez":"Claude independiente 2026-11-24 00:10 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"Complementa S2-C02 y S5-C13."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":132,"familia":"SECURITY"}]$pack$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=(p->>'legada_id')::int;
 SELECT id,regla,version,hash_paquete INTO e FROM lf_ops.nucleo_evaluaciones WHERE regla=cd AND version=(p->>'version')::int ORDER BY id DESC LIMIT 1;
 IF ((SELECT count(*) FROM lf_ops.reglas)=586 AND e.id IS DISTINCT FROM (p->>'eval_id')::bigint) OR e.hash_paquete IS DISTINCT FROM p->>'hash_paquete_atestado' OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=e.version)<>8 OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='CANDIDATA') THEN RAISE EXCEPTION 'S7_ATTESTATION_DRIFT %',cd; END IF;
 h:=lf_ops.nucleo_hash_paquete_v1(cd,e.version);
 IF h IS DISTINCT FROM e.hash_paquete THEN RAISE EXCEPTION 'S7_HASH_DRIFT %',cd; END IF;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto',p->>'veredicto','puntajes',p->'puntajes','juez',p->>'juez','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_s7_juicios_14_v1.json#'||cd);
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S7_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF p->>'veredicto'='DEVOLVER' THEN
 IF ans->>'decision'='AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='CANDIDATA') THEN RAISE EXCEPTION 'S7_RETURN_FAIL %',cd; END IF;
 ret:=ret+1;
 ELSE
 IF ans->>'decision'='AUTO' THEN
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado'<>'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S7_PROMOTION_FAIL % %',cd,ans; END IF;
 pub:=pub+1;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 diff:=diffs->>cd; status:=CASE WHEN cd='S5-C12' THEN 'PARCIAL' ELSE 'REEMPLAZADA' END; residual:=CASE WHEN cd='S5-C12' THEN 'Registro autoritativo de abandono no tiene columna de estado verificada.' ELSE '' END;
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,e.version,status,diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente S7 2026-11-24 00:10'),h,'GPT / Claude S7 independiente');
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S7_LEGACY_MISSING %',lid; END IF;
 ELSE RAISE NOTICE 'S7_PASS_NOT_AUTO % %',cd,ans; END IF;
 END IF;
 n:=n+1;
 END LOOP;
 IF n<>14 OR ret<>6 OR pub<>8 OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep THEN RAISE EXCEPTION 'S7_READBACK_FAIL n=% ret=% pub=%',n,ret,pub; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S7_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S7_PASS 14 JUICIOS 8 AUTO 6 RETENIDAS DPIG03=0';
END $j$;
DO $cfg$
BEGIN
 IF EXISTS(SELECT 1 FROM public.lf_global_config WHERE (scope,config_key) IN (('AUTH','GENERIC_SECURITY_MESSAGE'),('PAGOS','YAPE_RECURRING_ENABLED'))) THEN RAISE EXCEPTION 'S7_CONFIG_COLLISION'; END IF;
 INSERT INTO public.lf_global_config(scope,config_key,config_value,value_type,value_status,description) VALUES
 ('AUTH','GENERIC_SECURITY_MESSAGE','No pudimos procesar tu solicitud. Intenta nuevamente o contáctanos.','TEXT','REAL','Decisión Cristhian: mensaje genérico único anti-enumeración. Revisiones de reglas por circuito gobernado; no altera runtime.'),
 ('PAGOS','YAPE_RECURRING_ENABLED','false','BOOLEAN','REAL','Decisión Cristhian: recurrencia Yape deshabilitada hasta certificación Niubiz LF y Legal Q08. No habilita cobro ni sustituye consentimiento.');
 IF (SELECT count(*) FROM public.lf_global_config WHERE (scope,config_key,config_value,value_type,value_status) IN (('AUTH','GENERIC_SECURITY_MESSAGE','No pudimos procesar tu solicitud. Intenta nuevamente o contáctanos.','TEXT','REAL'),('PAGOS','YAPE_RECURRING_ENABLED','false','BOOLEAN','REAL')))<>2 THEN RAISE EXCEPTION 'S7_CONFIG_READBACK_FAIL'; END IF;
END $cfg$;
COMMIT;
